R = "manual-source-image"


def row(page, first, site, column, forms, uncertainties=None):
    return {
        "PDF_Page": page,
        "Printed_Page": page - 5,
        "First_Item": first,
        "Site": site,
        "Column": column,
        "Review": R,
        "Forms": forms,
        "Uncertainties": uncertainties or [""] * len(forms),
    }


def flags(length, mapping):
    values = [""] * length
    for offset, note in mapping.items():
        values[offset] = note
    return values


